import type { Condition, EarlierOp, NowOp } from "../../reads/where-ops.ts";
import { type CountOp, type ViewBlock } from "../../reads/views.ts";
import type { BranchChain, UnnamedStepNode, ChannelPattern, InstrumentedAction, Mapping, StepNode, WhenBuilder } from "../types.ts";
export { actionPattern } from "./nodes.ts";
/** Read matching occurrences strictly before a trigger in its causal flow. */
export declare function earlier(action: InstrumentedAction, input: Mapping, output?: Mapping): EarlierOp;
/** Bind a fresh variable to the instant stamped on this causal flow's outermost occurrence. */
export declare function now(variable: symbol): NowOp;
export declare function when(channel: ChannelPattern): WhenBuilder;
export declare function when(line: StepNode): WhenBuilder;
interface AuthoredWhereBlock extends ViewBlock {
    then(node: UnnamedStepNode): BranchChain;
}
/** State a read conjunction, optionally qualifying one reaction branch with it. */
export declare function where(...conditions: Array<Condition | CountOp>): AuthoredWhereBlock;
